<?php
declare(strict_types=1);require_once dirname(__DIR__).'/src/bootstrap.php';Auth::requireOwner();
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Auth::verifyCsrf();try{$op=(string)($_POST['op']??'');if($op==='save'){$id=AgentWorkflowService::saveTemplate(['workflow_key'=>$_POST['workflow_key']??'','name'=>$_POST['name']??'','description'=>$_POST['description']??'','steps_json'=>$_POST['steps_json']??'[]','enabled'=>1],(int)(Auth::user()['id']??1));$_SESSION['flash']='Workflow saved #'.$id;}elseif($op==='assign'){AgentWorkflowService::assign((int)$_POST['agent_id'],(int)$_POST['workflow_id'],true);$_SESSION['flash']='Workflow assigned.';}elseif($op==='run'){$w=(string)$_POST['workflow_key'];$r=AgentWorkflowService::execute((int)$_POST['agent_id'],$w,[]);$_SESSION['flash']='Workflow run #'.$r['run_id'].' completed.';}else throw new RuntimeException('workflow_builder_action_invalid');$_SESSION['flash_type']='success';}catch(Throwable $e){$_SESSION['flash']=AdminUi::humanError($e->getMessage());$_SESSION['flash_type']='error';}header('Location: /api/admin/workflow-builder.php');exit;}
$flows=AgentWorkflowService::templates(false);$agents=AgentService::all();AdminUi::header('Agent Workflow Builder','workflow_builder');echo AdminUi::flash();
?>
<div class="grid"><section class="card span-7"><div class="card-title"><div><h2>Reusable Workflows</h2><span class="muted small">Typed steps let you coordinate common work without writing a new PHP service for every sequence. Specialist Company OS 11 services remain the source of truth for their domains.</span></div></div><?php foreach($flows as $w):?><article class="card subtle" style="margin:8px 0"><div class="card-title"><div><b><?=e($w['name'])?></b><small class="muted" style="display:block"><?=e($w['workflow_key'])?> v<?=$w['version_no']??1?></small></div><?=AdminUi::badge($w['enabled']?'active':'disabled')?></div><p><?=e($w['description']??'')?></p><pre class="code-box"><?=e($w['steps_json'])?></pre><div class="actions"><form method="post"><?=AdminUi::csrf()?><input type="hidden" name="op" value="assign"><input type="hidden" name="workflow_id" value="<?=$w['id']?>"><select name="agent_id"><?php foreach($agents as $a):?><option value="<?=$a['id']?>"><?=e($a['display_name'])?></option><?php endforeach?></select><button class="btn small">Assign</button></form><form method="post"><?=AdminUi::csrf()?><input type="hidden" name="op" value="run"><input type="hidden" name="workflow_key" value="<?=e($w['workflow_key'])?>"><select name="agent_id"><?php foreach($agents as $a):?><option value="<?=$a['id']?>"><?=e($a['display_name'])?></option><?php endforeach?></select><button class="btn ghost small">Run</button></form></div></article><?php endforeach?></section>
<section class="card span-5"><div class="card-title"><h2>Create Workflow</h2></div><form method="post"><?=AdminUi::csrf()?><input type="hidden" name="op" value="save"><div class="field"><label>Workflow key</label><input name="workflow_key" pattern="[a-z0-9_.-]+" required></div><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Steps JSON</label><textarea name="steps_json" rows="15" required>[{"action":"create_task","params":{"agent_slug":"ramy","title":"Example","description":"Describe the work"}}]</textarea></div><p class="small muted">Allowed typed actions: notify_owner, create_task, web_search, resource_request, external_propose, request_media, security_run, set_followup.</p><button class="btn full-width">Save Workflow</button></form></section></div>
